create or replace function public.get_staff_collections_workspace()
returns jsonb language sql stable security definer set search_path=public,pg_temp as $$
 with overdue as (
  select l.id loan_id,l.institution_id,l.account_number,l.customer_profile_id,p.full_name,coalesce(c.mpesa_phone_number,p.phone_number) phone,
   coalesce(sum(i.principal_due+i.interest_due+i.fee_due+i.penalty_due-i.principal_paid-i.interest_paid-i.fee_paid-i.penalty_paid),0) overdue_amount,
   greatest(0,current_date-min(i.due_date)) days_past_due
  from public.loan_accounts l join public.customers c on c.profile_id=l.customer_profile_id and c.institution_id=l.institution_id join public.profiles p on p.id=c.profile_id and p.institution_id=c.institution_id join public.repayment_installments i on i.loan_account_id=l.id and i.institution_id=l.institution_id
  where l.institution_id=public.current_institution_id() and i.due_date<current_date and i.status not in ('paid','waived') group by l.id,l.institution_id,l.account_number,l.customer_profile_id,p.full_name,c.mpesa_phone_number,p.phone_number
 ), portfolio as (select coalesce(sum(principal_outstanding+interest_outstanding+fee_outstanding+penalty_outstanding),0) amount from public.loan_accounts where institution_id=public.current_institution_id() and status='active')
 select jsonb_build_object(
  'metrics',jsonb_build_object('par_1_30',coalesce((select sum(overdue_amount) from overdue where days_past_due between 1 and 30),0),'par_31_60',coalesce((select sum(overdue_amount) from overdue where days_past_due between 31 and 60),0),'par_61_90',coalesce((select sum(overdue_amount) from overdue where days_past_due between 61 and 90),0),'non_performing_ratio',case when (select amount from portfolio)>0 then round(coalesce((select sum(overdue_amount) from overdue where days_past_due>90),0)*100.0/(select amount from portfolio),2) else null end,'portfolio_balance',(select amount from portfolio)),
  'cases',coalesce((select jsonb_agg(jsonb_build_object('id',coalesce(cc.id,o.loan_id),'loan_id',o.loan_id,'loan_number',o.account_number,'customer_name',o.full_name,'phone',o.phone,'overdue_arrears',o.overdue_amount,'days_past_due',o.days_past_due,'ageing_bucket',case when o.days_past_due<=30 then 'PAR 1-30' when o.days_past_due<=60 then 'PAR 31-60' when o.days_past_due<=90 then 'PAR 61-90' else 'PAR 90+' end,'assigned_officer',coalesce(ap.full_name,'Unassigned'),'last_contact_date',(select max(ci.occurred_at) from public.collection_interactions ci where ci.collection_case_id=cc.id),'next_follow_up_date',null,'status',coalesce(cc.status,'open'),'promise_to_pay',(select jsonb_build_object('amount',pt.amount,'date',pt.promised_for) from public.promise_to_pay pt where pt.collection_case_id=cc.id and pt.status='open' order by pt.created_at desc limit 1)) order by o.days_past_due desc) from overdue o left join public.collection_cases cc on cc.loan_account_id=o.loan_id and cc.institution_id=o.institution_id and cc.status in ('open','paused') left join public.profiles ap on ap.id=cc.assigned_staff_profile_id),'[]'::jsonb)
 ) where public.has_permission('collections.read');
$$;
